cat > test/labels.test.ts <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { toResource } from "../src/api.ts";
import { branchOf, byBranch, isUntagged, matches } from "../src/filter.ts";
import type { BranchResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";
import { summarize } from "../src/report.ts";

function res(id: string, fields: Partial<BranchResource> = {}): BranchResource {
  return { id, type: "instance", name: id, tags: {}, stack_id: null, depends_on: [],
    cost_month_cents: 100, created_at: "2024-11-01T00:00:00Z", ...fields };
}

test("label selectors ignore key casing, not value casing; legacy tags take precedence", () => {
  const r = res("labelled", { labels: { BrAnCh: "feat-ledger", TEAM: "payments" } });
  assert.equal(branchOf(r), "feat-ledger");
  assert.equal(isUntagged(r), false);
  assert.ok(matches(r, [["branch", "feat-ledger"], ["team", "payments"]]));
  assert.ok(matches(r, [["TEAM", "payments"]]));
  assert.ok(!matches(r, [["branch", "FEAT-LEDGER"]]));
  assert.equal(branchOf({ ...r, tags: { branch: "main" } }), "main");
  assert.equal(branchOf(res("untagged")), undefined);
});

test("listing and summaries recognize label-only branch ownership", () => {
  const resources = [res("labelled", { labels: { Branch: "feat-ledger" } }), res("orphan")];
  assert.equal(byBranch(resources).get("feat-ledger")?.length, 1);
  assert.equal(byBranch(resources).get("(untagged)")?.length, 1);
  assert.match(summarize(resources), /feat-ledger/);
  assert.match(summarize(resources), /1 untagged resources/);
});

test("plan includes labels and exact stack ownership, never similarly named branches or unrelated dependencies", () => {
  const resources = [
    res("net", { type: "network", tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    res("boot", { type: "volume", stack_id: "stk-feat-ledger" }),
    res("label-volume", { type: "volume", labels: { Branch: "feat-ledger" } }),
    res("app", { labels: { BRANCH: "feat-ledger" }, depends_on: ["net", "boot", "label-volume"] }),
    res("custom-app", { labels: { Branch: "feat-ledger" }, stack_id: "custom-stack", depends_on: ["custom-volume"] }),
    res("custom-volume", { type: "volume", stack_id: "custom-stack" }),
    res("v2", { stack_id: "stk-feat-ledger-v2" }),
    res("other", { labels: { Branch: "feat-payroll" }, stack_id: "stk-feat-ledger" }),
    res("orphan"),
  ];
  const plan = buildPlan(resources, "feat-ledger");
  const ids = plan.steps.map((s) => s.id);
  assert.deepEqual([...ids].sort(), ["app", "boot", "custom-app", "custom-volume", "label-volume", "net"]);
  assert.deepEqual(plan.blocked, []);
  for (const r of resources.filter((r) => ids.includes(r.id))) {
    for (const dep of r.depends_on) assert.ok(ids.indexOf(r.id) < ids.indexOf(dep));
  }
  assert.equal(buildPlan(resources, "FEAT-LEDGER").steps.length, 0);
});

test("genuine external dependents still block teardown", () => {
  const plan = buildPlan([
    res("net", { labels: { Branch: "feat-ledger" } }),
    res("external", { labels: { Branch: "main" }, depends_on: ["net"] }),
  ], "feat-ledger");
  assert.deepEqual(plan.blocked, [{ id: "net", dependents: ["external"] }]);
});

test("shared normalization remains unchanged (CLI must preserve labels separately)", () => {
  assert.equal("labels" in toResource({ id: "labelled", labels: { Branch: "feat-ledger" } }), false);
});
EOF
