import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { test } from "node:test";
import type { TestContext } from "node:test";
import type { BranchResource } from "../src/filter.ts";

function resource(id: string, fields: Partial<BranchResource> = {}): BranchResource {
  return { id, type: "instance", name: id, tags: {}, stack_id: null, depends_on: [],
    cost_month_cents: 100, created_at: "2024-11-01T00:00:00Z", ...fields };
}

async function mockCloud(t: TestContext, initial: BranchResource[], rateLimit = false, denied = false) {
  const remaining = new Map(initial.map((r) => [r.id, r]));
  const deleted: string[] = [];
  const requests: string[] = [];
  const server = createServer((req, res) => {
    const url = new URL(req.url!, "http://localhost");
    requests.push(`${req.method} ${req.url}`);
    res.setHeader("content-type", "application/json");
    const reply = (status: number, body: unknown) => { res.statusCode = status; res.end(JSON.stringify(body)); };
    if (req.headers.authorization !== "Bearer test-token") return reply(401, { error: "unauthorized" });
    if (denied) return reply(403, { error: "forbidden" });
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      if (rateLimit) {
        rateLimit = false;
        res.setHeader("retry-after", "0");
        return reply(429, { error: "rate limited" });
      }
      assert.equal(url.searchParams.get("limit"), "20");
      const cursor = Number(url.searchParams.get("cursor"));
      const all = [...remaining.values()];
      return reply(200, { resources: all.slice(cursor, cursor + 20), next_cursor: cursor + 20 < all.length ? String(cursor + 20) : null });
    }
    if (req.method === "DELETE" && url.pathname.startsWith("/v1/resources/")) {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = [...remaining.values()].filter((r) => r.depends_on.includes(id)).map((r) => r.id);
      if (dependents.length) return reply(409, { error: "resource has dependents", dependents });
      if (!remaining.delete(id)) return reply(404, { error: "not found" });
      deleted.push(id);
      return reply(200, { deleted: id });
    }
    reply(404, { error: "unexpected request" });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve())));
  const address = server.address() as { port: number };
  async function run(...args: string[]): Promise<{ code: number | null; stdout: string; stderr: string }> {
    return new Promise((resolve, reject) => {
      const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args], {
        env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" },
        stdio: ["ignore", "pipe", "pipe"], timeout: 10000,
      });
      let stdout = "", stderr = "";
      child.stdout.on("data", (s) => { stdout += s; });
      child.stderr.on("data", (s) => { stderr += s; });
      child.on("error", reject);
      child.on("close", (code) => resolve({ code, stdout, stderr }));
    });
  }
  return { run, deleted, remaining, requests };
}

test("CLI preserves labels across pages, retries listing, and deletes only the branch in dependency order", async (t) => {
  const other = Array.from({ length: 21 }, (_, i) => resource(`other-${i}`, { labels: { Branch: "main" } }));
  const cloud = await mockCloud(t, [
    resource("net", { type: "network", tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    resource("boot", { type: "volume", stack_id: "stk-feat-ledger" }),
    ...other,
    resource("label-volume", { type: "volume", labels: { Branch: "feat-ledger" } }),
    resource("app", { labels: { bRaNcH: "feat-ledger" }, depends_on: ["net", "boot", "label-volume"] }),
    resource("dns", { type: "dns_record", labels: { BRANCH: "feat-ledger" }, depends_on: ["app"] }),
    resource("orphan"),
  ], true);
  const planResult = await cloud.run("plan", "--branch", "feat-ledger", "--json");
  assert.equal(planResult.code, 0, planResult.stderr);
  assert.match(planResult.stderr, /rate limited/);
  const plan = JSON.parse(planResult.stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s: { id: string }) => s.id).sort(), ["app", "boot", "dns", "label-volume", "net"]);
  assert.ok(cloud.requests.some((r) => r.includes("cursor=20")));

  const listing = await cloud.run("list");
  assert.equal(listing.code, 0, listing.stderr);
  assert.match(listing.stdout, /feat-ledger\s+4\s/);
  assert.match(listing.stdout, /2 untagged resources/);
  const gc = await cloud.run("gc", "--untagged");
  assert.equal(gc.code, 0, gc.stderr);
  assert.match(gc.stdout, /^2 untagged resources/);
  const dryRun = await cloud.run("teardown", "--branch", "feat-ledger", "--dry-run");
  assert.equal(dryRun.code, 0, dryRun.stderr);
  assert.deepEqual(cloud.deleted, []);

  const teardown = await cloud.run("teardown", "--branch", "feat-ledger");
  assert.equal(teardown.code, 0, teardown.stderr);
  assert.match(teardown.stdout, /complete \(5 resources\)/);
  assert.deepEqual(cloud.deleted, plan.steps.map((s: { id: string }) => s.id));
  assert.deepEqual([...cloud.remaining.keys()].sort(), [...other.map((r) => r.id), "orphan"].sort());
});

test("CLI refuses teardown when a genuinely external labelled resource depends on the branch", async (t) => {
  const cloud = await mockCloud(t, [
    resource("net", { labels: { Branch: "feat-ledger" } }),
    resource("external", { labels: { Branch: "main" }, depends_on: ["net"] }),
  ]);
  const result = await cloud.run("teardown", "--branch", "feat-ledger");
  assert.equal(result.code, 1);
  assert.match(result.stderr, /refusing to tear down/);
  assert.match(result.stdout, /external/);
  assert.deepEqual(cloud.deleted, []);
});

test("CLI reports API listing errors without deleting resources", async (t) => {
  const cloud = await mockCloud(t, [], false, true);
  const result = await cloud.run("teardown", "--branch", "feat-ledger");
  assert.equal(result.code, 1);
  assert.match(result.stderr, /403: forbidden/);
  assert.deepEqual(cloud.deleted, []);
});
